/**
 * Greetings shown on the welcome screen.
 */

export interface GreetOptions {
  /** Shown instead of the name when it is empty. */
  fallback?: string;
  /** Appended after the greeting. Defaults to "!". */
  suffix?: string;
}

const DEFAULT_FALLBACK = "friend";
const DEFAULT_SUFFIX = "!";

function clean(name: string): string {
  return name.trim().replace(/\s+/g, " ");
}

export function greet(name: string, options: GreetOptions = {}): string {
  const who = clean(name) || options.fallback || DEFAULT_FALLBACK;
  return `Hello, ${who}${options.suffix ?? DEFAULT_SUFFIX}`;
}

export function farewell(name: string): string {
  return `Goodbye, ${clean(name)}`;
}

