/**
 * Retry with exponential backoff for the job queue.
 */

// Start at 250 ms: at 100 ms every worker retried at once after an outage.
export const BACKOFF_MS = [250, 500, 1000, 2000];

export async function withRetry<T>(run: () => Promise<T>): Promise<T> {
  let lastError: unknown;
  for (const delay of BACKOFF_MS) {
    try {
      return await run();
    } catch (error) {
      lastError = error;
      await sleep(delay + Math.random() * delay * 0.1);
    }
  }
  throw lastError;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

